const D = { energy: .6, scale: 1, density: .5, wear: .5, speed: 1, hue: 210, x: .5, y: .44, alpha: 1, style: 'treadplate', act: 'drift', seed: 0 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const cl=(v,a,b)=>v<a?a:(v>b?b:v), md=(a,n)=>((a%n)+n)%n, TAU=Math.PI*2;
const sd=P.seed|0;
const fr=i=>{const s=Math.sin(i*127.1+sd*311.7)*43758.5453;return s-Math.floor(s);};
if(S.lb==null||K.beat<S.lb)S.lb=K.beat; S.lb=K.beat;

const W=width, Hh=height, u=Math.min(W,Hh);
const sty=P.style;
const pat=(sty==='patina'), haz=(sty==='hazard'), ano=(sty==='anodised');
const H=md(P.hue,360), AL=cl(P.alpha,0,1);
const en=cl(P.energy,0,1), sc=cl(P.scale,.4,2.4), dens=cl(P.density,0,1);
const spd=cl(P.speed,.1,4), wr=cl(P.wear,0,1.4), act=P.act;
const hz=cl(P.y,.26,.74)*Hh, cx=cl(P.x,.05,.95)*W, gH=Math.max(24,Hh-hz);

S.bass=(S.bass||0)*.84+(A.bass||0)*.16;
const T=K.t*spd;
const glow=(.34+.66*en)*(.55+.55*K.intensity)+S.bass*.28;

const yOf=t=>hz+Math.pow(cl(t,0,1),1.7)*gH;
const hwOf=t=>W*(.05+cl(t,0,1)*1.6)*.5*sc;

// ---- the beacon: a SMOOTH continuous sweep, never a flash.
// A pure rotation has |dAngle| over 8s = (8w mod 2pi) — a CONSTANT — so it can
// never re-phase (at spd=1 the wedge moves ~30 deg every 8s, always).
// Amplitude is held low on purpose: a hard beacon flash is exactly the strobe
// Gene has banned from the stage.
let bw=0.85;
if(act==='alarm') bw=1.35; else if(act==='shutdown') bw=0.30;
const ba=T*bw;
// and a slow independent sheen drift, so two unrelated things always move
const shU=.60*Math.sin(T*.091)+.27*Math.sin(T*.163+1.7)+.13*Math.sin(T*.271);

const NPX=Math.max(2,Math.round(3+dens*3));     // plates across
const NPY=Math.max(3,Math.round(4+dens*4));     // plates deep

// ---- the deck, baked once: plates, seams, welds, bolts, tread, paint -----
const bkey=[W,Hh,sty,sd,Math.round(H),Math.round(P.y*120),Math.round(P.x*120),Math.round(sc*40),Math.round(wr*6),NPX,NPY].join('|');
if(!S.base||S.bk!==bkey||S.base.width!==W||S.base.height!==Hh){
  const g=(S.base&&S.base.width===W&&S.base.height===Hh)?S.base:createGraphics(W,Hh);
  g.colorMode(HSB,360,100,100,100); g.clear(); g.noStroke();
  const cr=(S.crown&&S.crown.width===W&&S.crown.height===Hh)?S.crown:createGraphics(W,Hh);
  cr.colorMode(HSB,360,100,100,100); cr.clear(); cr.noStroke();
  const steelH=pat?md(H-176,360):(ano?md(H+150,360):H);

  // the plate, graded to the horizon
  const STR=54;
  for(let i=0;i<STR;i++){
    const t=i/STR, y=yOf(t), y2=yOf((i+1)/STR);
    let s2,b2;
    if(pat){ s2=34-12*t; b2=7+18*Math.pow(t,1.15); }
    else if(ano){ s2=48-14*t; b2=12+34*Math.pow(t,1.1); }
    else if(haz){ s2=8-3*t; b2=9+24*Math.pow(t,1.15); }
    else { s2=10-4*t; b2=8+24*Math.pow(t,1.15); }
    g.fill(steelH,cl(s2,0,70),cl(b2,2,90),100);
    g.rect(0,y-1,W,(y2-y)+2);
  }

  // ---- hazard paint goes UNDER the tread, as it does on a real deck -----
  if(haz){
    for(let i=0;i<26;i++){                       // chevrons across the near deck
      const t0=.30+(i/26)*.68, t1=.30+((i+1)/26)*.68;
      if((i&1)===0) continue;
      const hw0=hwOf(t0)*.72, hw1=hwOf(t1)*.72;
      g.fill(md(H+186,360),74,66,74);
      g.beginShape();
      g.vertex(cx-hw0,yOf(t0)); g.vertex(cx+hw0,yOf(t0));
      g.vertex(cx+hw1,yOf(t1)); g.vertex(cx-hw1,yOf(t1));
      g.endShape(CLOSE);
    }
    for(const soff of [-.78,.78]){               // keep-clear edge lines
      for(let i=0;i<24;i++){
        const t0=.06+(i/24)*.94, t1=.06+((i+1)/24)*.94;
        g.noFill(); g.strokeWeight(Math.max(.9,gH*.012*t0));
        g.stroke(md(H+186,360),70,60,70*(.3+.7*t0));
        g.line(cx+soff*hwOf(t0),yOf(t0),cx+soff*hwOf(t1),yOf(t1));
      }
      g.noStroke();
    }
  }

  // ---- the raised tread: alternating lozenge pairs, the signature of the plate
  const NLX=Math.round((16+dens*14)), NLY=Math.round((13+dens*11));
  for(let r=NLY;r>=0;r--){
    const t0=r/NLY, t1=(r+1)/NLY;
    if(t1<=.08) continue;
    const tm=(t0+t1)*.5, yc=yOf(tm), rowH=Math.max(1,yOf(t1)-yOf(t0)), hw=hwOf(tm);
    const dir=(r%4<2)?1:-1;                      // the pattern flips every two rows
    for(let c=-1;c<=NLX;c++){
      const sxn=((c+.5+((r&1)?.5:0))/NLX)*2-1;
      const x=cx+sxn*hw;
      if(x<-gH*.1||x>W+gH*.1) continue;
      const lw=(hw*2/NLX)*.52, lh=rowH*.34;
      if(lw<.7||lh<.5) continue;
      const id=r*61+c*17;
      const gone=pat&&fr(id*1.9)<(wr*.42);       // corrosion has eaten the tread away
      if(gone) continue;
      g.push(); g.translate(x,yc); g.rotate(dir*.62);
      // the lozenge body + its lit face + the shadow it throws on the plate
      g.fill(steelH,cl((pat?30:(ano?44:8))+6*fr(id*1.9+1),0,70),cl((pat?12:(ano?22:16))+16*fr(id*1.9+2),2,80),100);
      g.rect(-lw*.5,-lh*.5,lw,lh,Math.min(lw,lh)*.30);
      g.fill(steelH,cl((pat?24:(ano?32:5)),0,60),cl((pat?26:(ano?58:44))+18*fr(id*1.9+3),3,92),64);
      g.rect(-lw*.5,-lh*.5,lw,Math.max(.5,lh*.34),Math.min(lw,lh)*.24);
      g.fill(steelH,10,3,40);
      g.rect(-lw*.5,lh*.22,lw,Math.max(.5,lh*.3));
      g.pop();
      // the crown mask: where this lozenge CAN catch the beacon
      cr.push(); cr.translate(x,yc); cr.rotate(dir*.62);
      cr.fill(0,0,100,cl(60+38*fr(id*1.9+4),0,100));
      cr.rect(-lw*.44,-lh*.44,lw*.88,Math.max(.5,lh*.46),Math.min(lw,lh)*.22);
      cr.pop();
    }
  }

  // ---- plate seams, weld beads and countersunk bolts --------------------
  for(let j=0;j<=NPY;j++){                       // transverse butt joints
    const t=j/NPY; if(t<.05) continue;
    const y=yOf(t), hw=hwOf(t);
    g.fill(steelH,12,3,72); g.rect(cx-hw,y,hw*2,Math.max(.9,gH*.006*t));
    g.fill(steelH,8,pat?30:52,44); g.rect(cx-hw,y-gH*.004*t,hw*2,Math.max(.7,gH*.004*t));
    for(let b=0;b<Math.round(6+dens*8);b++){     // bolts along the seam
      const bx2=cx+((b+.5)/Math.round(6+dens*8)*2-1)*hw;
      const br=Math.max(.9,gH*.007*t);
      g.fill(steelH,10,pat?16:24,90); g.circle(bx2,y,br*2);
      g.fill(steelH,8,pat?26:50,80); g.circle(bx2,y-br*.22,br*1.2);
    }
  }
  for(let i=0;i<=NPX;i++){                       // longitudinal joints
    const soff=(i/NPX)*2-1;
    for(let k=0;k<24;k++){
      const t0=.05+(k/24)*.95, t1=.05+((k+1)/24)*.95;
      g.noFill(); g.strokeWeight(Math.max(.8,gH*.005*t0));
      g.stroke(steelH,12,3,66*(.3+.7*t0));
      g.line(cx+soff*hwOf(t0),yOf(t0),cx+soff*hwOf(t1),yOf(t1));
    }
    g.noStroke();
  }

  // ---- wear: rust bloom, oil soak, and the polished path feet have worn --
  if(!ano){
    const NC=Math.round(wr*(14+dens*12));
    for(let k=0;k<NC;k++){
      const t=.10+fr(k*7.3)*.88, y=yOf(t), hw=hwOf(t);
      const x=cx+(fr(k*7.3+1)*2-1)*hw;
      const rr=gH*(.02+fr(k*7.3+2)*.09)*t*(.5+wr);
      g.fill(md(H-176,360),44+fr(k*7.3+3)*24,14+fr(k*7.3+4)*20,32);
      g.ellipse(x,y,rr*2.4,rr*1.2);
      g.fill(md(H-182,360),50,7,24);
      g.ellipse(x+rr*.3,y+rr*.2,rr*1.6,rr*.7);
    }
    for(let k=0;k<Math.round(10+wr*10);k++){     // oil soaked into the tread
      const t=.14+fr(k*9.1+3)*.82, y=yOf(t), hw=hwOf(t);
      const x=cx+(fr(k*9.1+4)*2-1)*hw*.8;
      const rr=gH*(.03+fr(k*9.1+5)*.10)*t;
      g.fill(steelH,14,3,26); g.ellipse(x,y,rr*2.6,rr*1.0);
    }
  }
  S.base=g; S.bk=bkey; S.crown=cr;
}

const dc=drawingContext, oldOp=dc.globalCompositeOperation;
// BELOW THE HORIZON ONLY — the bg slot underneath must survive untouched
dc.save(); dc.beginPath(); dc.rect(0,hz,W,Hh-hz); dc.clip();
image(S.base,0,0);

// ---- the beacon wedge sweeping the deck, masked to the tread crowns ------
{
  if(!S.lit||S.lit.width!==W||S.lit.height!==Hh){
    if(S.lit) S.lit.remove();
    S.lit=createGraphics(W,Hh); S.lit.colorMode(HSB,360,100,100,100);
  }
  const lg=S.lit, lc=lg.drawingContext;
  lg.clear();
  const bx2=cx+Math.cos(ba)*W*.30, by2=hz+gH*.46+Math.sin(ba)*gH*.30;
  const bandC=ano?'200,226,255':(pat?'255,180,120':(haz?'255,206,120':'255,238,208'));
  const rr=gH*(1.05+.12*Math.sin(T*.067));
  const rg=lc.createRadialGradient(bx2,by2,0,bx2,by2,Math.max(6,rr));
  const pa=(0.62+0.38*glow)*AL;
  rg.addColorStop(0,'rgba('+bandC+','+pa.toFixed(3)+')');
  rg.addColorStop(.42,'rgba('+bandC+','+(pa*.36).toFixed(3)+')');
  rg.addColorStop(1,'rgba('+bandC+',0)');
  lc.fillStyle=rg; lc.fillRect(0,hz,W,gH);
  // a drifting anisotropic sheen — steel smears a reflection into a band
  const sx2=cx+shU*W*.55;
  const sg=lc.createLinearGradient(sx2-W*.22,0,sx2+W*.22,0);
  const sa=(0.34+0.30*glow)*AL;
  sg.addColorStop(0,'rgba('+bandC+',0)');
  sg.addColorStop(.5,'rgba('+bandC+','+sa.toFixed(3)+')');
  sg.addColorStop(1,'rgba('+bandC+',0)');
  lc.fillStyle=sg; lc.fillRect(0,hz,W,gH);
  // a standing wash so the tread never dies where neither light lands
  lc.fillStyle='rgba('+bandC+','+(0.12*(0.4+glow)*AL).toFixed(3)+')';
  lc.fillRect(0,hz,W,gH);
  lc.globalCompositeOperation='destination-in';
  lg.image(S.crown,0,0);
  lc.globalCompositeOperation='source-over';
  blendMode(ADD); image(lg,0,0); blendMode(BLEND);
}

// ---- the same beacon washing the plate itself, softly ------------------
{
  dc.globalCompositeOperation='lighter';
  const bx2=cx+Math.cos(ba)*W*.30, by2=hz+gH*.46+Math.sin(ba)*gH*.30;
  const rr=gH*.80;
  const c=ano?'160,200,255':(pat?'255,170,110':'255,226,170');
  const rg=dc.createRadialGradient(bx2,by2,0,bx2,by2,Math.max(6,rr));
  const aa=0.055*(0.4+glow)*AL;               // soft: a sweep, never a flash
  rg.addColorStop(0,'rgba('+c+','+aa.toFixed(4)+')');
  rg.addColorStop(1,'rgba('+c+',0)');
  dc.fillStyle=rg; dc.fillRect(0,hz,W,gH);
  dc.globalCompositeOperation=oldOp;
}

// ---- haze where the deck runs out of light -----------------------------
{
  const hgd=dc.createLinearGradient(0,hz,0,hz+gH*.32);
  const c=ano?'40,60,90':(pat?'52,34,26':'32,38,50');
  hgd.addColorStop(0,'rgba('+c+','+(0.60*AL).toFixed(3)+')');
  hgd.addColorStop(1,'rgba('+c+',0)');
  dc.fillStyle=hgd; dc.fillRect(0,hz,W,gH*.32);
}

dc.restore();
blendMode(BLEND); dc.globalCompositeOperation=oldOp; dc.globalAlpha=1; dc.shadowBlur=0;
noStroke(); noTint();
